// Auto-generated demo artwork (base64). Used for marketplace hero + demo listing thumbnails.
// Keys stored in DB as 'ff:char' etc. are resolved client-side via FF_THUMBS.

export const FF_HERO = "data:image/jpeg;base64,";
export const FF_CHAR = "data:image/jpeg;base64,";
export const FF_WEAPONS = "data:image/jpeg;base64,";
export const FF_TROPHY = "data:image/jpeg;base64,";

export const FF_THUMBS: Record<string, string> = {
  "ff:hero": FF_HERO,
  "ff:char": FF_CHAR,
  "ff:weapons": FF_WEAPONS,
  "ff:trophy": FF_TROPHY,
};

/** Resolve a listing image: 'ff:*' keys → inlined art, else the URL itself. */
export function resolveListingImage(src: string): string {
  if (src.startsWith("ff:")) return FF_THUMBS[src] ?? FF_CHAR;
  return src;
}
